sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    try {
        g_scratchpad.rule_category = current.rule_category.toString();
        g_scratchpad.assigned_to = current.assigned_to.toString();
        g_scratchpad.u_outcome = current.u_outcome.toString();
        g_scratchpad.collateral_task_type = current.collateral_task_type.toString();
        g_scratchpad.u_martini_reference_1 = current.u_martini_reference_1.toString();
        g_scratchpad.u_martini_reference_2 = current.u_martini_reference_2.toString();
        g_scratchpad.treats = current.treats ? current.treats.toString() : 'false';

        g_scratchpad.collateralTreatsSwitch = gs.getProperty('x_hsb11_mss_coll_0.Collateral_Treats_Switch');

        //get Maker Assigned
        g_scratchpad.maker_sys_id = '';
        var caseId = current.getValue('collateral_case_id');
        if (!caseId) return;
        var makergr = new GlideRecord('x_hsb11_mss_coll_0_collateral_task_table');
        makergr.addQuery('collateral_case_id', caseId);
        makergr.addQuery('collateral_task_type', 'Base Task');
        makergr.orderByDesc('sys_created_on');
        makergr.setLimit(1);
        makergr.query();
        if (makergr.next()) {
            g_scratchpad.maker_sys_id = makergr.getValue('assigned_to') || '';
            //gs.info('g_scratchpad.maker_sys_id - ' + g_scratchpad.maker_sys_id);
        }
        //get Maker Assigned


        // Recreated base Task Check
        g_scratchpad.checkerTaskExist = false;
        var caseID = current.getValue('collateral_case_id');
        if (!caseID) return;
        var checkerGr = new GlideRecord('x_hsb11_mss_coll_0_collateral_task_table');
        checkerGr.addQuery('collateral_task_type', 'Checker');
        checkerGr.addQuery('collateral_case_id', caseID);
        checkerGr.orderByDesc('sys_created_on');
        checkerGr.query();
        if (checkerGr.next()) {
            g_scratchpad.checkerTaskExist = true;
        }
        // Recreated base Task Check

    } catch (e) {
        gs.info('Error Recieved for Set Scratchpad Values ' + e);
    }

})(current, previous);
